sql.where:
created_at >= #{q.startTime} AND created_at < #{q.endTime}
 AND user_id = #{q.userId} 
 AND model_name = #{q.modelName} 
 AND business_scene = #{q.businessScene} 
 AND request_status = #{q.requestStatus} 
 AND usage_status = #{q.usageStatus} 
 AND total_cost >= #{q.minCost} 
 AND total_cost <= #{q.maxCost}

mapper.select:
SELECT * FROM ai_token_usage

ORDER BY ${q.sort}
LIMIT #{limit} OFFSET #{offset}

SELECT COALESCE(SUM(total_cost), 0) FROM ai_token_usage
WHERE request_status = 'SUCCESS'
  AND created_at >= #{from} AND created_at < #{to}
 AND user_id = #{userId}

SELECT COALESCE(SUM(total_cost), 0) FROM ai_token_usage
WHERE request_status = 'SUCCESS' AND usage_status <> 'MOCK'
  AND created_at >= #{from} AND created_at < #{to}
 AND user_id = #{userId}
